    .ptr-filters,.ptr-table-card{border:1px solid var(--line);border-radius:14px;background:#fff}.ptr-filters{display:flex;align-items:end;gap:12px;flex-wrap:wrap;padding:14px}.ptr-field,.ptr-period{display:flex;flex-direction:column;gap:5px}.ptr-period{border-left:1px solid var(--line);padding-left:12px}.ptr-field label,.ptr-label{font-size:10px;font-weight:800;letter-spacing:.06em;text-transform:uppercase;color:var(--mute)}.ptr-field input,.ptr-field select{height:37px;padding:0 10px;border:1px solid #cbd5e1;border-radius:9px;background:#fff;font:inherit;font-size:13px;color:var(--ink)}.ptr-field select{min-width:230px}.ptr-btn{height:37px;padding:0 14px;border:1px solid var(--green);border-radius:9px;background:var(--green);color:#fff;font:inherit;font-size:13px;font-weight:700;cursor:pointer}.ptr-btn:hover{background:var(--deep)}.ptr-btn.secondary{margin-left:auto;background:#fff;color:var(--green)}.ptr-month,.ptr-week{height:37px;display:flex;align-items:center;border:1px solid var(--line);border-radius:10px;overflow:hidden}.ptr-month button,.ptr-week button{height:100%;width:34px;border:0;background:#f6fbf9;color:var(--green);font-size:18px;font-weight:800;cursor:pointer}.ptr-month button:hover,.ptr-week button:hover{background:#e5f5ee}.ptr-month span{min-width:150px;text-align:center;font-size:12px;font-weight:800;color:var(--deep)}.ptr-week span{min-width:260px;text-align:center;font-size:11px;font-weight:800;color:var(--deep)}
    .ptr-kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.ptr-kpi{border:1px solid var(--line);border-radius:14px;background:#fff;padding:15px 17px}.ptr-kpi span{display:block;font-size:11px;font-weight:800;letter-spacing:.06em;text-transform:uppercase;color:var(--mute)}.ptr-kpi strong{display:block;margin-top:4px;font-size:30px;line-height:1;color:var(--green)}.ptr-kpi.off strong{color:#dc2626}.ptr-kpi.rate strong{color:#1d4ed8}.ptr-kpi.tally strong{color:#7c3aed}.ptr-table-card{overflow:hidden}.ptr-table-head{padding:15px 16px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;align-items:center;gap:12px}.ptr-table-head h2{margin:0;font-size:15px}.ptr-table-head span{font-size:12px;color:var(--mute)}.ptr-table{width:100%;border-collapse:collapse}.ptr-table th{padding:11px 15px;text-align:left;background:#f8fafc;border-bottom:1px solid var(--line);font-size:10px;font-weight:800;letter-spacing:.06em;text-transform:uppercase;color:var(--mute)}.ptr-sort{display:inline-flex;align-items:center;gap:5px;padding:0;border:0;background:transparent;color:inherit;font:inherit;font-weight:inherit;letter-spacing:inherit;text-transform:inherit;cursor:pointer}.ptr-sort:hover{color:var(--deep)}.ptr-sort:focus-visible{outline:2px solid var(--green);outline-offset:3px;border-radius:3px}.ptr-sort-arrow{font-size:14px;line-height:1;color:var(--green)}.ptr-table td{padding:13px 15px;border-bottom:1px solid #edf3f1;font-size:13px}.ptr-table tr:last-child td{border-bottom:0}.ptr-person{font-weight:700}.ptr-sub{display:block;margin-top:2px;font-size:11px;color:var(--mute)}.ptr-time{font-variant-numeric:tabular-nums;font-weight:700}.ptr-badge{display:inline-flex;align-items:center;gap:6px;padding:5px 9px;border:1px solid;border-radius:999px;font-size:10px;font-weight:800;letter-spacing:.05em}.ptr-badge:before{content:'';width:6px;height:6px;border-radius:50%;background:currentColor}.ptr-badge.on{background:#dcfce7;border-color:#86efac;color:#15803d}.ptr-badge.off{background:#fef2f2;border-color:#fecaca;color:#dc2626}.ptr-action{padding:7px 10px;border:1px solid #93d9b7;border-radius:8px;background:#fff;color:#047857;font:inherit;font-size:11px;font-weight:800;cursor:pointer}.ptr-action:hover{background:#edf9f2}.ptr-empty{padding:42px 18px;text-align:center;color:var(--mute);font-size:13px}
    .ptr-modal-back{position:fixed;inset:0;z-index:1200;display:none;align-items:center;justify-content:center;padding:20px;background:rgba(15,23,42,.45)}.ptr-modal-back.open{display:flex}.ptr-modal{width:min(900px,100%);max-height:min(78vh,720px);overflow:auto;border-radius:16px;background:#fff;box-shadow:0 18px 60px rgba(15,23,42,.25)}.ptr-modal-head{display:flex;align-items:flex-start;justify-content:space-between;padding:18px 20px;border-bottom:1px solid var(--line)}.ptr-modal-head h2{font-size:17px;margin:0}.ptr-modal-head p{margin:4px 0 0;font-size:12px;color:var(--mute)}.ptr-modal-close{width:30px;height:30px;border:0;border-radius:8px;background:#f1f5f9;color:#475569;font-size:20px;cursor:pointer}.ptr-modal-table{width:100%;border-collapse:collapse}.ptr-modal-table th,.ptr-modal-table td{padding:12px 16px;text-align:left;border-bottom:1px solid #edf3f1;font-size:12px}.ptr-modal-table th{background:#f8fafc;color:var(--mute);font-size:10px;letter-spacing:.06em;text-transform:uppercase}.ptr-modal-empty{padding:35px;text-align:center;color:var(--mute);font-size:13px}@media(max-width:900px){.ptr-kpis{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:700px){.content{padding:16px!important}.ptr-hero{align-items:flex-start;flex-direction:column}.ptr-kpis{grid-template-columns:1fr}.ptr-period{border-left:0;padding-left:0;width:100%}.ptr-month,.ptr-week{width:max-content}.ptr-week span{min-width:230px}.ptr-btn.secondary{margin-left:0}.ptr-table-card{overflow:auto}.ptr-table{min-width:820px}.ptr-modal{max-height:85vh}.ptr-modal-table{min-width:680px}}
