<body><div class="overlay" id="overlay"></div><div class="shell"><?php $sb_base='..'; include('../includes/sidebar.php'); ?><div class="main-area"><?php include('../includes/header.php'); ?><main class="content"><section class="ptr-wrap">
  <header class="ptr-hero"><div><div class="ptr-kicker">Turno actual · Control de registro</div><h1>Puntualidad y tallys por coordinador</h1><p>Control administrativo de aperturas de turno, tallys registrados y las zonas de asistencia por turno.</p></div><div class="ptr-window"><b>Ventanas válidas</b>Turno día: 06:00–08:00 · Turno noche: 18:00–20:00</div></header>
  <div class="ptr-filters"><div class="ptr-period"><span class="ptr-label">Mes</span><div class="ptr-month"><button type="button" id="ptrPrevMonth" aria-label="Mes anterior">‹</button><span id="ptrMonthLabel">—</span><button type="button" id="ptrNextMonth" aria-label="Mes siguiente">›</button></div></div><div class="ptr-period"><span class="ptr-label">Semana</span><div class="ptr-week"><button type="button" id="ptrPrevWeek" aria-label="Semana anterior">‹</button><span id="ptrWeekLabel">—</span><button type="button" id="ptrNextWeek" aria-label="Semana siguiente">›</button></div></div><div class="ptr-field"><label for="ptrDesde">Desde</label><input id="ptrDesde" type="date"></div><div class="ptr-field"><label for="ptrHasta">Hasta</label><input id="ptrHasta" type="date"></div><div class="ptr-field"><label for="ptrCoord">Coordinador</label><select id="ptrCoord"><option value="">Todos los coordinadores</option></select></div><button class="ptr-btn" id="ptrBuscar">Actualizar reporte</button><button class="ptr-btn secondary" id="ptrClear">Ver todos los registros</button><button class="ptr-btn secondary" id="ptrExport">Exportar Excel</button></div>
  <div class="ptr-kpis"><article class="ptr-kpi"><span>Registros a tiempo</span><strong id="ptrOn">0</strong></article><article class="ptr-kpi off"><span>Registros fuera de tiempo</span><strong id="ptrOff">0</strong></article><article class="ptr-kpi rate"><span>Cumplimiento</span><strong id="ptrRate">—</strong></article><article class="ptr-kpi tally"><span>Tallys registrados</span><strong id="ptrTallyCount">0</strong></article></div>
  <div class="ptr-table-card"><div class="ptr-table-head"><h2>Detalle de registros</h2><span id="ptrCount">Cargando…</span></div><table class="ptr-table"><thead><tr><th>Coordinador</th><th aria-sort="descending"><button type="button" class="ptr-sort" id="ptrOrder" title="Ordenar por fecha y turno"><span>Fecha</span><span class="ptr-sort-arrow" aria-hidden="true">↓</span></button></th><th>Turno</th><th>Hora de registro</th><th>Tallys registrados</th><th>Horas realizadas</th><th>Estado</th><th>Acción</th></tr></thead><tbody id="ptrRows"></tbody></table><div class="ptr-empty" id="ptrEmpty" hidden>No hay registros de turno para los filtros seleccionados.</div></div>
</section></main></div></div>
<div class="ptr-modal-back" id="ptrModalBack" role="dialog" aria-modal="true" aria-labelledby="ptrModalTitle"><div class="ptr-modal"><div class="ptr-modal-head"><div><h2 id="ptrModalTitle">Tallys asignados</h2><p id="ptrModalSub">—</p></div><button type="button" class="ptr-modal-close" id="ptrModalClose" aria-label="Cerrar">×</button></div><div id="ptrModalBody"></div></div></div>
<script>
(() => {const $=id=>document.getElementById(id);let rows=[],tallysPorTurno={},coords=[],monthCursor=new Date(),weekCursor=new Date(),order='desc';const MONTHS=['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];const iso=d=>{const x=new Date(d);x.setMinutes(x.getMinutes()-x.getTimezoneOffset());return x.toISOString().slice(0,10)},short=d=>String(d.getDate()).padStart(2,'0')+'/'+String(d.getMonth()+1).padStart(2,'0')+'/'+d.getFullYear(),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmtHoras=m=>{m=Number(m||0);return Math.floor(m/60)+' h'+(m%60?' '+String(m%60).padStart(2,'0')+' min':'')};
function setRange(a,b){$('ptrDesde').value=iso(a);$('ptrHasta').value=iso(b)}function applyMonth(){const y=monthCursor.getFullYear(),m=monthCursor.getMonth();$('ptrMonthLabel').textContent=MONTHS[m]+' de '+y;setRange(new Date(y,m,1),new Date(y,m+1,0));load()}function weekStart(d){const x=new Date(d);x.setHours(0,0,0,0);x.setDate(x.getDate()-((x.getDay()+6)%7));return x}function isoWeek(d){const x=new Date(Date.UTC(d.getFullYear(),d.getMonth(),d.getDate()));x.setUTCDate(x.getUTCDate()+4-(x.getUTCDay()||7));const ys=new Date(Date.UTC(x.getUTCFullYear(),0,1));return Math.ceil((((x-ys)/86400000)+1)/7)}function applyWeek(){const a=weekStart(weekCursor),b=new Date(a);b.setDate(a.getDate()+6);$('ptrWeekLabel').textContent='Semana '+isoWeek(a)+' · '+short(a)+' – '+short(b);setRange(a,b);load()}function tallysFor(id){return tallysPorTurno[String(id)]||[]}
 function openTallys(id){const r=rows.find(x=>String(x.id)===String(id));if(!r)return;const list=tallysFor(id);$('ptrModalTitle').textContent='Tallys asignados · '+r.coordinador;$('ptrModalSub').textContent=r.fecha+' · '+r.jornada+' · '+list.length+' tally'+(list.length===1?'':'s')+' registrado'+(list.length===1?'':'s');$('ptrModalBody').innerHTML=list.length?`<table class="ptr-modal-table"><thead><tr><th>Tally</th><th>Código</th><th>Posición</th><th>Zona donde asistió</th><th>Equipo</th><th>Horas realizadas</th></tr></thead><tbody>${list.map(t=>`<tr><td><b>${esc(t.nombre)}</b></td><td>${esc(t.codigo||'—')}</td><td>${esc(t.posicion||t.tipo_funcion||'—')}</td><td>${esc(t.zona||'Sin zona asignada')}</td><td>${esc(t.cuadrilla||'—')}</td><td><b>${fmtHoras(t.minutos_turno)}</b></td></tr>`).join('')}</tbody></table>`:'<div class="ptr-modal-empty">No se registraron tallys vinculados a este coordinador en este turno.</div>';$('ptrModalBack').classList.add('open')}function closeTallys(){$('ptrModalBack').classList.remove('open')}
 function orderedRows(){const direction=order==='desc'?-1:1;return [...rows].sort((a,b)=>{const aKey=a.fecha+(a.jornada_codigo==='N'?'1':'0'),bKey=b.fecha+(b.jornada_codigo==='N'?'1':'0');return aKey===bKey?0:(aKey>bKey?direction:-direction)})}function render(){const on=rows.filter(r=>r.estado_puntualidad==='on').length,off=rows.length-on,total=rows.reduce((s,r)=>s+Number(r.tallys_registrados||0),0),ordered=orderedRows();$('ptrOn').textContent=on;$('ptrOff').textContent=off;$('ptrRate').textContent=rows.length?Math.round(on*100/rows.length)+'%':'—';$('ptrTallyCount').textContent=total;$('ptrCount').textContent=rows.length+' registro'+(rows.length===1?'':'s');$('ptrEmpty').hidden=!!rows.length;$('ptrOrder').setAttribute('aria-label','Ordenar por fecha y turno: '+(order==='desc'?'más reciente primero':'más antiguo primero'));$('ptrOrder').title=$('ptrOrder').getAttribute('aria-label');$('ptrOrder').querySelector('.ptr-sort-arrow').textContent=order==='desc'?'↓':'↑';$('ptrOrder').closest('th').setAttribute('aria-sort',order==='desc'?'descending':'ascending');$('ptrRows').innerHTML=ordered.map(r=>`<tr><td><span class="ptr-person">${esc(r.coordinador)}</span></td><td>${esc(r.fecha)}</td><td><span class="ptr-person">${esc(r.jornada)}</span><span class="ptr-sub">${r.jornada_codigo==='N'?'Noche':'Día'}</span></td><td class="ptr-time">${esc(r.hora_registro)}</td><td><span class="ptr-person">${Number(r.tallys_registrados||0)}</span><span class="ptr-sub">tallys en turno</span></td><td><span class="ptr-person">${fmtHoras(r.minutos_turno)}</span><span class="ptr-sub">del turno registrado</span></td><td><span class="ptr-badge ${r.estado_puntualidad}">${r.estado_puntualidad==='on'?'ON TIME':'OFF TIME'}</span></td><td><button type="button" class="ptr-action" data-turno="${r.id}">Ver tallys y zonas</button></td></tr>`).join('')}
async function load(){const p=new URLSearchParams({desde:$('ptrDesde').value,hasta:$('ptrHasta').value});if($('ptrCoord').value)p.set('coordinador',$('ptrCoord').value);$('ptrCount').textContent='Actualizando…';try{const d=await fetch('../api/get_reporte_puntualidad.php?'+p,{cache:'no-store'}).then(r=>r.json());if(!d.success)throw Error(d.error);const selected=$('ptrCoord').value;coords=d.coordinadores||[];$('ptrCoord').innerHTML='<option value="">Todos los coordinadores</option>'+coords.map(c=>`<option value="${c.id}">${esc(c.nombre)} (${c.tally_count} tallys)</option>`).join('');$('ptrCoord').value=selected;rows=d.registros||[];tallysPorTurno=d.tallys_por_turno||{};render()}catch(e){rows=[];tallysPorTurno={};render();$('ptrCount').textContent=e.message||'No se pudo cargar el reporte'}}
 function exportExcel(){if(!window.XLSX){alert('No se pudo cargar el módulo de Excel.');return}const ordered=orderedRows(),a=[['Coordinador','Fecha','Turno','Hora de registro','Tallys registrados','Horas realizadas','Estado'],...ordered.map(r=>[r.coordinador,r.fecha,r.jornada,r.hora_registro,r.tallys_registrados,fmtHoras(r.minutos_turno),r.estado_puntualidad==='on'?'ON TIME':'OFF TIME'])],b=[['Coordinador','Fecha','Turno','Código','Tally','Posición','Zona donde asistió','Equipo','Horas realizadas'],...ordered.flatMap(r=>tallysFor(r.id).map(t=>[r.coordinador,r.fecha,r.jornada,t.codigo,t.nombre,t.posicion||t.tipo_funcion,t.zona,t.cuadrilla,fmtHoras(t.minutos_turno)]))],book=XLSX.utils.book_new();XLSX.utils.book_append_sheet(book,XLSX.utils.aoa_to_sheet(a),'Puntualidad');XLSX.utils.book_append_sheet(book,XLSX.utils.aoa_to_sheet(b),'Tallys y zonas');XLSX.writeFile(book,'reporte_puntualidad_y_tallys.xlsx')}
 $('ptrPrevMonth').addEventListener('click',()=>{monthCursor.setMonth(monthCursor.getMonth()-1);applyMonth()});$('ptrNextMonth').addEventListener('click',()=>{monthCursor.setMonth(monthCursor.getMonth()+1);applyMonth()});$('ptrPrevWeek').addEventListener('click',()=>{weekCursor.setDate(weekCursor.getDate()-7);applyWeek()});$('ptrNextWeek').addEventListener('click',()=>{weekCursor.setDate(weekCursor.getDate()+7);applyWeek()});$('ptrBuscar').addEventListener('click',load);$('ptrCoord').addEventListener('change',load);$('ptrOrder').addEventListener('click',()=>{order=order==='desc'?'asc':'desc';render()});$('ptrExport').addEventListener('click',exportExcel);$('ptrRows').addEventListener('click',e=>{const b=e.target.closest('[data-turno]');if(b)openTallys(b.dataset.turno)});$('ptrModalClose').addEventListener('click',closeTallys);$('ptrModalBack').addEventListener('click',e=>{if(e.target===$('ptrModalBack'))closeTallys()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeTallys()});applyMonth()})();
</script>
<script>
// Restablece el reporte a un rango que incluye todo el historial disponible.
document.getElementById('ptrClear').addEventListener('click', () => {
  document.getElementById('ptrDesde').value = '2000-01-01';
  document.getElementById('ptrHasta').value = '2100-12-31';
  document.getElementById('ptrCoord').value = '';
  document.getElementById('ptrBuscar').click();
});
</script></body></html>
